import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
API_SECRET = os.environ.get('API_SECRET', 'default-hmac-key')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, dbname=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def verify_request_signature(payload, signature):
    """Verify HMAC-SHA256 signature of request body"""
    expected = hmac.new(API_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    page = request.args.get('page', '1')
    limit = request.args.get('limit', '20')

    # Input length validation
    if len(username) > 100 or len(department) > 100:
        return jsonify({'error': 'Input too long'}), 400

    # Build dynamic query based on provided filters
    conditions = []
    if username:
        conditions.append(f"username ILIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Note: pagination uses parameterized values
    query = f"SELECT id, username, email, department, role FROM users WHERE {where_clause} ORDER BY username LIMIT %s OFFSET %s"

    try:
        page_int = max(1, int(page))
        limit_int = min(50, max(1, int(limit)))
    except ValueError:
        return jsonify({'error': 'Invalid pagination'}), 400

    offset = (page_int - 1) * limit_int

    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(query, (limit_int, offset))
        rows = cur.fetchall()
        results = [
            {'id': r[0], 'username': r[1], 'email': r[2],
             'department': r[3], 'role': r[4]}
            for r in rows
        ]
        return jsonify({'results': results, 'page': page_int, 'limit': limit_int})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'Internal error'}), 500
    finally:
        conn.close()

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query"""
    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute("SELECT id, username, email, department, role FROM users WHERE id = %s", (user_id,))
        row = cur.fetchone()
        if not row:
            return jsonify({'error': 'Not found'}), 404
        return jsonify({'id': row[0], 'username': row[1], 'email': row[2],
                       'department': row[3], 'role': row[4]})
    finally:
        conn.close()

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
